from pathlib import Path


def replace_once(text: str, old: str, new: str, label: str) -> str:
    if old not in text:
        raise SystemExit(f"anchor missing: {label}")
    return text.replace(old, new, 1)


path = Path("pages/4_Projection_History.py")
text = path.read_text(encoding="utf-8")

text = replace_once(
    text,
    "from engine.team_leash import team_leash_walk_forward_report\n",
    "from engine.team_leash import team_leash_walk_forward_report\nfrom engine.projection_crushers import crusher_report, directional_k_result\n",
    "crusher import",
)

anchor = '''st.caption("HIT means the final result landed inside that market's frozen pregame 80% range. MISS means it finished outside the archived range.")\n\nst.divider()\nst.subheader("🧠 Current model learning status")\n'''
replacement = '''st.caption("80% range HIT means the final result landed inside that market's frozen pregame interval. Range coverage is calibration evidence, not directional win/loss grading.")\n\nst.divider()\nst.subheader("🔥 K Projection Wins & Crushers")\nst.caption(\n    "Directional K grading uses one strict rule: actual strikeouts > the frozen projected K mean = ✅ WIN; otherwise = ❌ MISS. "\n    "This is separate from 80% range coverage and does not feed the baseball forecast, calibration, or Top Plays ranking."\n)\n_directional_ready = df["projection"].notna() & df["actual_strikeouts"].notna()\n_directional = df.loc[_directional_ready].copy()\nif _directional.empty:\n    st.info("Directional K wins will appear as frozen projections resolve.")\nelse:\n    _directional["K Margin"] = pd.to_numeric(_directional["actual_strikeouts"], errors="coerce") - pd.to_numeric(_directional["projection"], errors="coerce")\n    _directional["Directional K Result"] = _directional.apply(lambda r: directional_k_result(r.get("projection"), r.get("actual_strikeouts")), axis=1)\n    _wins = int(_directional["Directional K Result"].eq("✅ WIN").sum())\n    _win_rate = float(_wins / len(_directional)) if len(_directional) else float("nan")\n    _crushers = crusher_report(df)\n    _crusher_count = int(_crushers["Crusher Status"].eq("🔥 CRUSHER").sum()) if not _crushers.empty else 0\n    kw1, kw2, kw3, kw4 = st.columns(4)\n    kw1.metric("Resolved K calls", len(_directional))\n    kw2.metric("Projection wins", _wins)\n    kw3.metric("Directional win rate", f"{_win_rate:.1%}")\n    kw4.metric("Consistent crushers", _crusher_count)\n\n    high_calls = _directional.loc[_directional.get("confidence", pd.Series(index=_directional.index, dtype=str)).astype(str).str.upper().eq("HIGH")].copy()\n    if not high_calls.empty:\n        st.markdown("#### High-confidence calls")\n        high_calls = high_calls.sort_values(["game_date", "captured_at_utc"], ascending=[False, False]).head(30)\n        high_view = high_calls[["player", "projection", "actual_strikeouts", "K Margin", "Directional K Result"]].copy()\n        high_view = high_view.rename(columns={"player":"Pitcher", "projection":"Projection", "actual_strikeouts":"Actual", "Directional K Result":"Result"})\n        high_styled = high_view.style.format({"Projection":"{:.2f}", "Actual":"{:.0f}", "K Margin":"{:+.2f}"}, na_rep="—")\n        high_styled = high_styled.map(lambda _: "color:#22c55e;font-weight:800;", subset=["Projection"])\n        high_styled = high_styled.map(lambda _: "color:#facc15;font-weight:800;", subset=["Actual"])\n        st.dataframe(high_styled, hide_index=True, width="stretch")\n\n    st.markdown("#### Projection Crushers")\n    if _crushers.empty:\n        st.info("Crusher tracking will populate as current starter-only K projections resolve.")\n    else:\n        crusher_view = _crushers.copy()\n        for col in ["Win Rate", "Recent 5 Win Rate"]:\n            crusher_view[col] = crusher_view[col].map(lambda x: "—" if pd.isna(x) else f"{float(x):.1%}")\n        for col in ["Avg K Margin", "Avg Win Margin", "Total K Above Projection"]:\n            crusher_view[col] = crusher_view[col].map(lambda x: "—" if pd.isna(x) else f"{float(x):+.2f}")\n        st.dataframe(crusher_view, hide_index=True, width="stretch")\n        st.caption("🔥 CRUSHER requires at least 3 resolved current-model starts, a win rate of at least 66.7%, and average actual Ks more than 0.5 above projection. This board is descriptive tracking only.")\n\nst.divider()\nst.subheader("🧠 Current model learning status")\n'''
text = replace_once(text, anchor, replacement, "directional section")

old = '''display["k_result"] = display.apply(lambda r: range_result(r, "actual_strikeouts", "k_range_low", "k_range_high"), axis=1)\ndisplay["hits_result"] = display.apply(lambda r: range_result(r, "actual_hits_allowed", "hits_range_low", "hits_range_high"), axis=1)\n'''
new = '''display["k_directional_result"] = display.apply(lambda r: directional_k_result(r.get("projection"), r.get("actual_strikeouts")), axis=1)\ndisplay["k_range_result"] = display.apply(lambda r: range_result(r, "actual_strikeouts", "k_range_low", "k_range_high"), axis=1)\ndisplay["hits_result"] = display.apply(lambda r: range_result(r, "actual_hits_allowed", "hits_range_low", "hits_range_high"), axis=1)\n'''
text = replace_once(text, old, new, "archive K grading")

old_columns = '''display_columns = [\n    "game_date", "player", "team", "opponent", "starter_history_games", "starter_history_source", "starter_history_mlb_games", "starter_history_observation_games",\n    "projection", "k_range_low", "k_range_high", "actual_strikeouts", "k_result", "k_error",\n    "hits_projection", "hits_range_low", "hits_range_high", "actual_hits_allowed", "hits_result", "hits_error",\n    "outs_projection", "outs_range_low", "outs_range_high", "actual_outs", "outs_result", "outs_error",\n    "status", "confidence", "data_quality", "history_semantics",\n]\ndisplay_columns = [col for col in display_columns if col in display.columns]\n\nst.dataframe(\n    display[display_columns],\n'''
new_columns = '''display_columns = [\n    "game_date", "player", "team", "opponent",\n    "projection", "actual_strikeouts", "k_directional_result", "k_error", "k_range_low", "k_range_high", "k_range_result",\n    "hits_projection", "actual_hits_allowed", "hits_error", "hits_range_low", "hits_range_high", "hits_result",\n    "outs_projection", "actual_outs", "outs_error", "outs_range_low", "outs_range_high", "outs_result",\n    "confidence", "data_quality", "starter_history_games", "starter_history_source", "starter_history_mlb_games", "starter_history_observation_games",\n    "status", "history_semantics",\n]\ndisplay_columns = [col for col in display_columns if col in display.columns]\narchive_view = display[display_columns].copy()\n# Remove dead archive columns instead of rendering blank visual tracks/cells.\narchive_populated = []\nfor col in archive_view.columns:\n    series = archive_view[col]\n    populated = series.notna()\n    if series.dtype == object:\n        populated = populated & series.astype(str).str.strip().ne("") & series.astype(str).str.lower().ne("nan")\n    if bool(populated.any()):\n        archive_populated.append(col)\narchive_view = archive_view[archive_populated]\n\narchive_formats = {}\nfor col in ["projection", "hits_projection", "outs_projection", "k_error", "hits_error", "outs_error"]:\n    if col in archive_view.columns:\n        archive_formats[col] = "{:+.2f}" if col.endswith("_error") else "{:.2f}"\nfor col in ["actual_strikeouts", "actual_hits_allowed", "actual_outs", "k_range_low", "k_range_high", "hits_range_low", "hits_range_high", "outs_range_low", "outs_range_high", "starter_history_games", "starter_history_mlb_games", "starter_history_observation_games"]:\n    if col in archive_view.columns:\n        archive_formats[col] = "{:.0f}"\narchive_styled = archive_view.style.format(archive_formats, na_rep="—")\nprojected_cols = [c for c in ["projection", "hits_projection", "outs_projection"] if c in archive_view.columns]\nactual_cols = [c for c in ["actual_strikeouts", "actual_hits_allowed", "actual_outs"] if c in archive_view.columns]\nif projected_cols:\n    archive_styled = archive_styled.map(lambda _: "color:#22c55e;font-weight:800;", subset=projected_cols)\nif actual_cols:\n    archive_styled = archive_styled.map(lambda _: "color:#facc15;font-weight:800;", subset=actual_cols)\n\nst.caption("Archive scan order: matchup → projected vs actual → directional result/margin → 80% range context → supporting audit fields. Completely empty columns are hidden automatically.")\nst.dataframe(\n    archive_styled,\n'''
text = replace_once(text, old_columns, new_columns, "archive table cleanup")

text = replace_once(
    text,
    '        "k_result": st.column_config.TextColumn("K Result"),\n',
    '        "k_directional_result": st.column_config.TextColumn("Directional K Result"),\n        "k_range_result": st.column_config.TextColumn("80% Range Result"),\n',
    "archive K config",
)

path.write_text(text, encoding="utf-8")

# Add UI contract checks to an existing page contract file.
test_path = Path("tests/test_projection_history_learning_dashboard.py")
test = test_path.read_text(encoding="utf-8")
addition = '''\n\ndef test_projection_history_directional_wins_and_clean_archive():\n    text = _page_text()\n    assert "K Projection Wins & Crushers" in text\n    assert "actual strikeouts > the frozen projected K mean" in text\n    assert "Projection Crushers" in text\n    assert "Directional K Result" in text\n    assert "80% Range Result" in text\n    assert "archive_populated" in text\n    assert "Completely empty columns are hidden automatically" in text\n    assert "#22c55e" in text\n    assert "#facc15" in text\n'''
if "test_projection_history_directional_wins_and_clean_archive" not in test:
    test += addition
test_path.write_text(test, encoding="utf-8")
